# Technical section: analyst-aware deferral's full deciding table (P3-T3.df1, verdicts as symbols), moved here by
# entry 6; and the forest graph P3-F8.
show3 = ["result_id", "comparison", "team", "capacity_label", "measure", "estimate (mean of 5)", "adjusted interval", "seed range", "versions 1 to 5", "verdict_mean_of_5", "verdict", "verdict_route", "labels"]
t = T33.copy()
for c in ("verdict", "verdict_mean_of_5"):
    t[c] = L.symbols(t[c], deciding=(c == "verdict"))
