forest(T33, 'Analyst-aware deferral: the 66 results that decide, with their widened ranges (square: average of the five versions; dots: the five versions)', "P3-F8_forest.png", ('forest.row-p3', '{comparison}, capacity {capacity}: {verdict}', {'comparison': {'1': 'team A against full automation', '2': 'team B against full automation', '3': 'team C against full automation', '4': 'team A against naive review', '5': 'team B against naive review', '6': 'team C against naive review'}}))
